// StrategyRuntimeServiceHandler is an implementation of the ant.v1.StrategyRuntimeService service.
type StrategyRuntimeServiceHandler interface {
	Execute(context.Context, *connect.Request[v1.ExecuteStrategyRequest]) (*connect.Response[v1.ExecuteStrategyResponse], error)
	Validate(context.Context, *connect.Request[v1.ValidateStrategyRequest]) (*connect.Response[v1.ValidateStrategyResponse], error)
	Backtest(context.Context, *connect.Request[v1.BacktestStrategyRequest]) (*connect.Response[v1.BacktestStrategyResponse], error)
	StartBacktestRun(context.Context, *connect.Request[v1.StartBacktestRunRequest]) (*connect.Response[v1.StartBacktestRunResponse], error)
	GetBacktestRun(context.Context, *connect.Request[v1.GetBacktestRunRequest]) (*connect.Response[v1.GetBacktestRunResponse], error)
	ListBacktestRuns(context.Context, *connect.Request[v1.ListBacktestRunsRequest]) (*connect.Response[v1.ListBacktestRunsResponse], error)
	WatchBacktestRun(context.Context, *connect.Request[v1.WatchBacktestRunRequest], *connect.ServerStream[v1.BacktestRunUpdate]) error
	CancelBacktestRun(context.Context, *connect.Request[v1.CancelBacktestRunRequest]) (*connect.Response[v1.CancelBacktestRunResponse], error)
	DeleteBacktestRun(context.Context, *connect.Request[v1.DeleteBacktestRunRequest]) (*connect.Response[v1.DeleteBacktestRunResponse], error)
	DeleteBacktestRuns(context.Context, *connect.Request[v1.DeleteBacktestRunsRequest]) (*connect.Response[v1.DeleteBacktestRunsResponse], error)
	GetTemplates(context.Context, *connect.Request[emptypb.Empty]) (*connect.Response[v1.GetStrategyTemplatesResponse], error)
	// ExecuteLive: proto-native live/paper strategy execution.
	// Go LiveStrategyRunner sends proto-native LiveStrategyContext (no JSON).
	ExecuteLive(context.Context, *connect.Request[v1.ExecuteLiveRequest]) (*connect.Response[v1.ExecuteLiveResponse], error)
	// AnalyzeCode analyzes MQL source and returns strategy intent summary + param panel + blind spots.
	AnalyzeImportCode(context.Context, *connect.Request[v1.AnalyzeImportCodeRequest]) (*connect.Response[v1.AnalyzeImportCodeResponse], error)
	// GenerateImportCode generates Go SDK code from analyzed MQL source.
	GenerateImportCode(context.Context, *connect.Request[v1.GenerateImportCodeRequest]) (*connect.Response[v1.GenerateImportCodeResponse], error)
	// ImportStrategy runs the full import pipeline: analyze → generate → return code.
	ImportStrategy(context.Context, *connect.Request[v1.ImportStrategyRequest]) (*connect.Response[v1.ImportStrategyResponse], error)
	// GetImportedStrategy retrieves a previously imported strategy by ID.
	GetImportedStrategy(context.Context, *connect.Request[v1.GetImportedStrategyRequest]) (*connect.Response[v1.GetImportedStrategyResponse], error)
	// ListStrategyRuns returns recent live/paper strategy run records.
	ListStrategyRuns(context.Context, *connect.Request[v1.ListStrategyRunsRequest]) (*connect.Response[v1.ListStrategyRunsResponse], error)
	// GetStrategyRun returns a single strategy run by ID.
	GetStrategyRun(context.Context, *connect.Request[v1.GetStrategyRunRequest]) (*connect.Response[v1.GetStrategyRunResponse], error)
	// ListActiveStrategies returns currently running strategy sessions.
	ListActiveStrategies(context.Context, *connect.Request[v1.ListActiveStrategiesRequest]) (*connect.Response[v1.ListActiveStrategiesResponse], error)
	// GetActiveStrategy returns a single active strategy session by run ID.
	GetActiveStrategy(context.Context, *connect.Request[v1.GetActiveStrategyRequest]) (*connect.Response[v1.GetActiveStrategyResponse], error)
	// StopStrategy cancels a running strategy session by run ID.
	StopStrategy(context.Context, *connect.Request[v1.StopStrategyRequest]) (*connect.Response[v1.StopStrategyResponse], error)
	// WatchStrategySignals streams real-time signals from a running strategy.
	WatchStrategySignals(context.Context, *connect.Request[v1.WatchStrategySignalsRequest], *connect.ServerStream[v1.StrategySignalEvent]) error
	// StartStrategy launches a new live or paper strategy run.
	StartStrategy(context.Context, *connect.Request[v1.StartStrategyRequest]) (*connect.Response[v1.StartStrategyResponse], error)
	// WatchActiveStrategies streams the active strategy list, pushing updates
	// whenever sessions are registered, deregistered, or change state.
	WatchActiveStrategies(context.Context, *connect.Request[v1.WatchActiveStrategiesRequest], *connect.ServerStream[v1.WatchActiveStrategiesEvent]) error
	// ListStrategyVersions returns version history for a strategy.
	ListStrategyVersions(context.Context, *connect.Request[v1.ListStrategyVersionsRequest]) (*connect.Response[v1.ListStrategyVersionsResponse], error)
	// GetStrategyVersion retrieves a specific version snapshot.
	GetStrategyVersion(context.Context, *connect.Request[v1.GetStrategyVersionRequest]) (*connect.Response[v1.GetStrategyVersionResponse], error)
	// RollbackStrategyVersion restores strategy code from a specific version.
	RollbackStrategyVersion(context.Context, *connect.Request[v1.RollbackStrategyVersionRequest]) (*connect.Response[v1.RollbackStrategyVersionResponse], error)
	// DiffStrategyVersions returns two version snapshots for client-side diffing.
	DiffStrategyVersions(context.Context, *connect.Request[v1.DiffStrategyVersionsRequest]) (*connect.Response[v1.DiffStrategyVersionsResponse], error)
	// UpdateStrategyCode updates the source code of an existing strategy and creates a version snapshot.
	UpdateStrategyCode(context.Context, *connect.Request[v1.UpdateStrategyCodeRequest]) (*connect.Response[v1.UpdateStrategyCodeResponse], error)
}

